function solveNQueens(n) {
  const result = [];
  const cols = new Set();
  const diag1 = new Set(); // r - c
  const diag2 = new Set(); // r + c
  const placement = new Array(n).fill(-1); // placement[row] = col

  function backtrack(row) {
    if (row === n) {
      const board = placement.map(
        (c) => ".".repeat(c) + "Q" + ".".repeat(n - c - 1)
      );
      result.push(board);
      return;
    }

    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag1.has(row - c) || diag2.has(row + c)) continue;

      cols.add(c);
      diag1.add(row - c);
      diag2.add(row + c);
      placement[row] = c;

      backtrack(row + 1);

      cols.delete(c);
      diag1.delete(row - c);
      diag2.delete(row + c);
    }
  }

  backtrack(0);
  return result;
}

