// Solution order doesn't matter for this judge: it sorts the boards
// (by joining each board's rows into one string) before comparing.
function solveNQueensJudge(n) {
  const solutions = solveNQueens(n);
  return solutions
    .map((board) => board.slice())
    .sort((a, b) => {
      const aKey = a.join("");
      const bKey = b.join("");
      return aKey < bKey ? -1 : aKey > bKey ? 1 : 0;
    });
}
